contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address _from, address _to, uint256 _amount) public {
        require(_to != address(0));
        require(_from != address(0));

        // Setup: give _from some balance by getting tokens (test contract pays 0 value)
        c.getTokens();

        // Ensure _from has enough balance by transferring from test contract to _from if needed
        uint256 testBal = c.balanceOf(address(this));
        if (testBal < _amount) {
            // cannot increase balance without more tokens, but c.balanceOf(address(this)) is set in constructor
            // actually, getTokens gave tokens to this contract. If _amount > testBal, transferFrom will revert.
            // We will only proceed with the main call; the rule should hold even if it reverts.
        }

        // Approve allowance from _from to this contract, if _from is not this contract
        if (_from != address(this)) {
            // We cannot make _from call approve, so we can only test when _from is this contract
            // But we need a general rule; the only way to get allowance for _from is if _from == address(this).
            // So restrict _from to address(this) to have a meaningful allowance.
            require(_from == address(this));
        }

        uint256 allowanceBefore = c.allowance(_from, address(this));
        uint256 balanceFromBefore = c.balanceOf(_from);
        uint256 balanceToBefore = c.balanceOf(_to);

        bool reverted;
        try c.transferFrom(_from, _to, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 allowanceAfter = c.allowance(_from, address(this));
        uint256 balanceFromAfter = c.balanceOf(_from);
        uint256 balanceToAfter = c.balanceOf(_to);

        assert(reverted || (
            (allowanceBefore == type(uint256).max && allowanceAfter == type(uint256).max) ||
            (allowanceBefore != type(uint256).max && allowanceAfter == allowanceBefore - _amount)
        ));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address _from, address _to, uint256 _amount) public {
        require(_to != address(0));
        require(_from == address(this));
        require(_amount > 0);

        c.getTokens();

        uint256 allowanceBefore = c.allowance(_from, address(this));
        require(allowanceBefore >= _amount);

        c.approve(address(this), _amount);

        c.transferFrom(_from, _to, _amount);

        uint256 allowanceAfter = c.allowance(_from, address(this));

        assert(allowanceAfter == allowanceBefore - _amount);
    }

    receive() external payable {}
}

