        require(_approveAmount >= _amount);

        c.approve(address(this), _approveAmount);

        uint256 allowanceBefore = c.allowance(_from, address(this));
        require(allowanceBefore >= _amount);

        c.transferFrom(_from, address(this), _amount);

        uint256 allowanceAfter = c.allowance(_from, address(this));

        assert(allowanceAfter == allowanceBefore - _amount);

        return;
    }

    receive() external payable {}
}

